const drawFirefly = () => {
  // Draw jar
  ctx.fillStyle = '#888';
  ctx.fillRect(50, 50, 300, 300);

  // Draw jar lid
  ctx.fillStyle = '#666';
  ctx.fillRect(50, 50, 300, 20);

  // Draw jar inside
  ctx.fillStyle = '#111';
  ctx.fillRect(60, 70, 280, 260);

  // Draw firefly body
  ctx.fillStyle = '#333';
  ctx.fillRect(180, 180, 40, 10);

  // Draw firefly head
  ctx.fillStyle = '#222';
  ctx.fillRect(160, 175, 20, 20);

  // Draw firefly wings
  ctx.fillStyle = '#444';
  ctx.fillRect(180, 160, 40, 15);
  ctx.fillRect(180, 205, 40, 15);

  // Draw firefly light
  ctx.fillStyle = '#ff0';
  ctx.beginPath();
  ctx.arc(200, 185, 8, 0, Math.PI * 2);
  ctx.fill();

  // Draw light glow
  ctx.fillStyle = '#ffff0044';
  ctx.beginPath();
  ctx.arc(200, 185, 15, 0, Math.PI * 2);
  ctx.fill();
};

drawFirefly();

