    ctx.fillRect(x, y, 10, 30);

    // Rocket fins
    ctx.fillStyle = '#cc3333';
    ctx.fillRect(x - 3, y + 25, 3, 8);
    ctx.fillRect(x + 10, y + 25, 3, 8);

    // Rocket nose
    ctx.fillStyle = '#ff3333';
    ctx.beginPath();
    ctx.moveTo(x + 5, y);
    ctx.lineTo(x, y + 8);
    ctx.lineTo(x + 10, y + 8);
    ctx.closePath();
    ctx.fill();

    // Rocket windows
    ctx.fillStyle = '#66ccff';
    ctx.fillRect(x + 2, y + 10, 6, 4);
}

// Draw flame
function drawFlame(x, y) {
    ctx.fillStyle = '#ff9900';
    ctx.beginPath();
    ctx.moveTo(x, y + 30);
    ctx.lineTo(x - 5, y + 40);
    ctx.lineTo(x + 15, y + 40);
    ctx.closePath();
    ctx.fill();

    ctx.fillStyle = '#ffff00';
    ctx.beginPath();
    ctx.moveTo(x, y + 30);
    ctx.lineTo(x - 3, y + 35);
    ctx.lineTo(x + 8, y + 35);
    ctx.closePath();
    ctx.fill();
}

// Animation
