let rocketY = H - 20;
let thrust = 0;
let velocity = 0;
let time = 0;

function drawRocket() {
    // Clear and redraw space
    ctx.fillStyle = '#000';
    ctx.fillRect(0, 0, W, H);

    // Redraw stars
    ctx.fillStyle = '#fff';
    for (let i = 0; i < 100; i++) {
        const x = Math.random() * W;
        const y = Math.random() * H;
        const size = Math.random() * 2;
        ctx.fillRect(x, y, size, size);
    }

    // Redraw ground
    ctx.fillStyle = '#555';
    ctx.fillRect(0, H - 20, W, 20);

    // Rocket body
    ctx.fillStyle = '#f00';
    ctx.fillRect(190, rocketY, 20, 40);

    // Rocket top
    ctx.fillStyle = '#ff0';
    ctx.beginPath();
    ctx.moveTo(190, rocketY);
    ctx.lineTo(210, rocketY);
    ctx.lineTo(200, rocketY - 15);
    ctx.closePath();
    ctx.fill();

    // Rocket windows
    ctx.fillStyle = '#0ff';
    ctx.fillRect(195, rocketY + 10, 10, 10);

    // Rocket flames
    if (time < 100) {
        ctx.fillStyle = '#ff0';
        ctx.beginPath();
        ctx.moveTo(195, rocketY + 40);
        ctx.lineTo(205, rocketY + 40 + thrust);
        ctx.lineTo(215, rocketY + 40);
        ctx.closePath();
        ctx.fill();

        ctx.fillStyle = '#f80';
        ctx.beginPath();
        ctx.moveTo(195, rocketY + 40);
        ctx.lineTo(205, rocketY + 40 + thrust * 0.7);
        ctx.lineTo(215, rocketY + 40);
        ctx.closePath();
        ctx.fill();
    }

    // Update rocket position
    if (time < 100) {
        thrust = Math.sin(time * 0.2) * 10 + 15;
        velocity = velocity - 0.2; // gravity
        rocketY = rocketY + velocity;
        time++;
    }
}

// Animate the rocket
let frame = 0;
const animate = () => {
    if (frame < 200) {
        drawRocket();
        frame++;
        requestAnimationFrame(animate);
    }
};

