// Animation loop
function animate() {
    // Clear canvas
    ctx.fillStyle = '#000';
    ctx.fillRect(0, 0, W, H);

    // Redraw stars
    ctx.fillStyle = '#fff';
    for (let i = 0; i < 100; i++) {
        const x = Math.random() * W;
        const y = Math.random() * H;
        const size = Math.random() * 2;
        ctx.fillRect(x, y, size, size);
    }

    // Redraw ground
    ctx.fillStyle = '#555';
    ctx.fillRect(0, H - 20, W, 20);

    // Update rocket position
    rocketY -= 2;
    thrust = Math.min(thrust + 0.2, 30);

    // Draw rocket body
    ctx.fillStyle = '#ff4444';
    ctx.fillRect(190, rocketY, 20, 40);

    // Draw rocket nose
    ctx.fillStyle = '#ff8800';
    ctx.beginPath();
    ctx.moveTo(190, rocketY);
    ctx.lineTo(210, rocketY);
    ctx.lineTo(200, rocketY - 10);
    ctx.closePath();
    ctx.fill();

    // Draw rocket fins
    ctx.fillStyle = '#ff4444';
    ctx.fillRect(185, rocketY + 25, 10, 10);
    ctx.fillRect(205, rocketY + 25, 10, 10);

    // Draw thrust flames
    if (thrust > 0) {
        ctx.fillStyle = '#ff8800';
        ctx.beginPath();
        ctx.moveTo(200, rocketY + 40);
        ctx.lineTo(190, rocketY + 40 + thrust);
        ctx.lineTo(210, rocketY + 40 + thrust);
        ctx.closePath();
        ctx.fill();

        // Draw flame sparks
        ctx.fillStyle = '#ffff00';
        for (let i = 0; i < 5; i++) {
            const sparkX = 195 + Math.random() * 10;
            const sparkY = rocketY + 40 + thrust + Math.random() * 10;
            const sparkSize = Math.random() * 3;
            ctx.fillRect(sparkX, sparkY, sparkSize, sparkSize);
        }
    }

    // Continue animation until rocket leaves screen
    if (rocketY > -50) {
        requestAnimationFrame(animate);
    }
}

