const drawGhost = () => {
  // Draw graveyard background
  ctx.fillStyle = '#1a1a1a';
  ctx.fillRect(0, 0, W, H);

  // Draw moon
  ctx.fillStyle = '#f0f0f0';
  ctx.beginPath();
  ctx.arc(320, 60, 30, 0, Math.PI * 2);
  ctx.fill();

  // Draw ghost body
  ctx.fillStyle = '#f8f8f8';
  ctx.beginPath();
  ctx.arc(200, 200, 60, 0, Math.PI * 2);
  ctx.fill();

  // Draw ghost eyes
  ctx.fillStyle = '#000';
  ctx.beginPath();
  ctx.arc(180, 190, 8, 0, Math.PI * 2);
  ctx.arc(220, 190, 8, 0, Math.PI * 2);
  ctx.fill();

  // Draw ghost pupils
  ctx.fillStyle = '#fff';
  ctx.beginPath();
  ctx.arc(180, 190, 3, 0, Math.PI * 2);
  ctx.arc(220, 190, 3, 0, Math.PI * 2);
  ctx.fill();

  // Draw ghost mouth
  ctx.beginPath();
  ctx.arc(200, 220, 15, 0, Math.PI);
  ctx.strokeStyle = '#000';
  ctx.lineWidth = 2;
  ctx.stroke();

  // Draw ghost arms
  ctx.fillStyle = '#f8f8f8';
  ctx.fillRect(120, 180, 20, 30);
  ctx.fillRect(260, 180, 20, 30);

  // Draw graveyard stones
  ctx.fillStyle = '#444';
  for (let i = 0; i < 15; i++) {
    const x = Math.random() * W;
    const y = Math.random() * H;
    const size = 5 + Math.random() * 15;
    ctx.fillRect(x, y, size, size);
  }

  // Draw gravestones
  ctx.fillStyle = '#888';
  for (let i = 0; i < 8; i++) {
    const x = 30 + i * 50;
    const y = 300 + Math.sin(i) * 20;
    ctx.fillRect(x, y, 15, 40);
    ctx.fillRect(x - 5, y, 25, 10);
  }
};

