        ctx.fillRect(x, y, size, size);
    }

    // Fireworks
    class Firework {
        constructor() {
            this.x = Math.random() * W;
            this.y = H;
            this.targetY = Math.random() * H * 0.6;
            this.speed = 2 + Math.random() * 3;
            this.color = `hsl(${Math.random() * 360}, 100%, 60%)`;
            this.trail = [];
            this.exploded = false;
            this.particles = [];
        }

        update() {
            if (!this.exploded) {
                this.y -= this.speed;
                this.trail.push({x: this.x, y: this.y});
                if (this.trail.length > 10) this.trail.shift();

                if (this.y <= this.targetY || Math.random() < 0.02) {
                    this.explode();
                }
            } else {
                for (let i = 0; i < this.particles.length; i++) {
                    this.particles[i].update();
                }
            }
        }

        draw() {
            if (!this.exploded) {
                // Draw trail
                for (let i = 0; i < this.trail.length; i++) {
                    const point = this.trail[i];
                    const alpha = i / this.trail.length;
                    ctx.fillStyle = `rgba(255, 255, 255, ${alpha * 0.5})`;
                    ctx.fillRect(point.x, point.y, 2, 2);
                }
                // Draw firework head
                ctx.fillStyle = this.color;
                ctx.fillRect(this.x - 3, this.y - 3, 6, 6);
            } else {
                for (let i = 0; i < this.particles.length; i++) {
                    this.particles[i].draw();
                }
            }
        }

        explode() {
            this.exploded = true;
            const particleCount = 100 + Math.floor(Math.random() * 50);
            for (let i = 0; i < particleCount; i++) {
                this.particles.push(new Particle(this.x, this.y, this.color));
            }
        }
    }

    class Particle {
        constructor(x, y, color) {
            this.x = x;
            this.y = y;
            this.color = color;
            this.vx = (Math.random() - 0.5) * 6;
            this.vy = (Math.random() - 0.5) * 6;
            this.size = Math.random() * 2 + 1;
            this.life = 30 + Math.floor(Math.random() * 30);
        }

        update() {
            this.x += this.vx;
            this.y += this.vy;
            this.vy += 0.1; // gravity
            this.life--;
        }

        draw() {
            if (this.life > 0) {
                ctx.fillStyle = this.color;
                ctx.globalAlpha = this.life / 60;
                ctx.fillRect(this.x, this.y, this.size, this.size);
                ctx.globalAlpha = 1;
            }
        }
    }

    const fireworks = [];

    function animate() {
        ctx.fillStyle = 'rgba(0, 0, 0, 0.1)';
        ctx.fillRect(0, 0, W, H);

        // Draw stars again for persistence
        ctx.fillStyle = '#fff';
        for (let i = 0; i < 50; i++) {
            const x = Math.random() * W;
            const y = Math.random() * H;
            const size = Math.random() * 1.5;
            ctx.fillRect(x, y, size, size);
        }

        // Update and draw fireworks
        for (let i = fireworks.length - 1; i >= 0; i--) {
            fireworks[i].update();
            fireworks[i].draw();
            if (fireworks[i].exploded && fireworks[i].particles.length === 0) {
                fireworks.splice(i, 1);
            }
        }

        // Create new fireworks occasionally
        if (Math.random() < 0.02) {
            fireworks.push(new Firework());
        }

        requestAnimationFrame(animate);
    }

    animate();

