const drawHedgehogBall = () => {
  // Background
  ctx.fillStyle = '#87CEEB';
  ctx.fillRect(0, 0, W, H);

  // Ground
  ctx.fillStyle = '#8B4513';
  ctx.fillRect(0, 350, W, 50);

  // Hedgehog ball body
  ctx.fillStyle = '#228B22';
  ctx.beginPath();
  ctx.arc(200, 300, 60, 0, Math.PI * 2);
  ctx.fill();

  // Spikes
  ctx.fillStyle = '#006400';
  for (let i = 0; i < 24; i++) {
    const angle = (i / 24) * Math.PI * 2;
    const x = 200 + Math.cos(angle) * 50;
    const y = 300 + Math.sin(angle) * 50;
    const length = 15 + Math.random() * 10;
    const spikeX = x + Math.cos(angle) * length;
    const spikeY = y + Math.sin(angle) * length;

    ctx.beginPath();
    ctx.moveTo(x, y);
    ctx.lineTo(spikeX, spikeY);
    ctx.lineWidth = 2;
    ctx.stroke();
  }

  // Eyes
  ctx.fillStyle = '#000';
  ctx.fillRect(180, 280, 8, 8);
  ctx.fillRect(212, 280, 8, 8);

  // Nose
  ctx.fillStyle = '#000';
  ctx.fillRect(195, 310, 10, 5);

  // Mouth
  ctx.beginPath();
  ctx.arc(200, 320, 5, 0, Math.PI);
  ctx.strokeStyle = '#000';
  ctx.lineWidth = 2;
  ctx.stroke();
};

