const drawWizard = () => {
  // Background
  ctx.fillStyle = '#1a1a2e';
  ctx.fillRect(0, 0, W, H);

  // Ground
  ctx.fillStyle = '#16213e';
  ctx.fillRect(0, 300, W, 100);

  // Wizard's robe
  ctx.fillStyle = '#4a4e69';
  ctx.fillRect(150, 200, 100, 100);

  // Wizard's chest
  ctx.fillStyle = '#222';
  ctx.fillRect(170, 220, 60, 60);

  // Wizard's head
  ctx.fillStyle = '#f8f9fa';
  ctx.beginPath();
  ctx.arc(200, 160, 30, 0, Math.PI * 2);
  ctx.fill();

  // Wizard's eyes
  ctx.fillStyle = '#000';
  ctx.beginPath();
  ctx.arc(190, 155, 4, 0, Math.PI * 2);
  ctx.arc(210, 155, 4, 0, Math.PI * 2);
  ctx.fill();

  // Wizard's beard
  ctx.fillStyle = '#f8f9fa';
  ctx.beginPath();
  ctx.arc(200, 180, 20, 0, Math.PI);
  ctx.fill();

  // Wizard's hat
  ctx.fillStyle = '#8d99ae';
  ctx.fillRect(170, 130, 60, 20);
  ctx.beginPath();
  ctx.moveTo(160, 150);
  ctx.lineTo(240, 150);
  ctx.lineTo(200, 120);
  ctx.closePath();
  ctx.fill();

  // Wizard's staff
  ctx.fillStyle = '#d9d9d9';
  ctx.fillRect(240, 180, 10, 120);

  // Staff orb
  ctx.fillStyle = '#ff6b6b';
  ctx.beginPath();
  ctx.arc(245, 170, 10, 0, Math.PI * 2);
  ctx.fill();

  // Magic spell effect
  ctx.fillStyle = 'rgba(255, 255, 255, 0.3)';
  for (let i = 0; i < 5; i++) {
    ctx.beginPath();
    ctx.arc(245, 170, 20 + i * 10, 0, Math.PI * 2);
    ctx.fill();
  }

  // Floating particles
  ctx.fillStyle = '#ffd166';
  for (let i = 0; i < 10; i++) {
    const x = Math.random() * W;
    const y = Math.random() * 200;
    const size = Math.random() * 3 + 1;
    ctx.beginPath();
    ctx.arc(x, y, size, 0, Math.PI * 2);
    ctx.fill();
  }
};

