// Draw flames
function drawFlame(x, y) {
    ctx.fillStyle = '#ff9900';
    ctx.beginPath();
    ctx.moveTo(x, y);
    ctx.lineTo(x + 20, y);
    ctx.lineTo(x + 10, y + 20);
    ctx.closePath();
    ctx.fill();

    ctx.fillStyle = '#ff6600';
    ctx.beginPath();
    ctx.moveTo(x + 5, y);
    ctx.lineTo(x + 15, y);
