    // Clear canvas
    ctx.fillStyle = '#000';
    ctx.fillRect(0, 0, W, H);

    // Redraw stars
    ctx.fillStyle = '#fff';
    for (let i = 0; i < 100; i++) {
        const x = Math.random() * W;
        const y = Math.random() * H;
        const size = Math.random() * 2;
        ctx.fillRect(x, y, size, size);
