const drawChameleon = () => {
  // Background
  ctx.fillStyle = '#87CEEB';
  ctx.fillRect(0, 0, W, H);

  // Branch
  ctx.fillStyle = '#8B4513';
  ctx.fillRect(150, 300, 100, 20);

  // Branch details
  ctx.fillStyle = '#A0522D';
  ctx.fillRect(145, 300, 5, 20);
  ctx.fillRect(245, 300, 5, 20);

  // Chameleon body
  ctx.fillStyle = '#32CD32';
  ctx.fillRect(170, 250, 80, 40);

  // Chameleon head
  ctx.fillRect(240, 240, 40, 40);

  // Chameleon eyes
  ctx.fillStyle = '#FFFFFF';
  ctx.fillRect(250, 245, 8, 8);
  ctx.fillRect(260, 245, 8, 8);
  ctx.fillStyle = '#000000';
  ctx.fillRect(252, 247, 4, 4);
  ctx.fillRect(262, 247, 4, 4);

  // Chameleon tongue
  ctx.fillStyle = '#FF69B4';
  ctx.fillRect(275, 260, 20, 4);

  // Chameleon legs
  ctx.fillStyle = '#32CD32';
  ctx.fillRect(170, 280, 8, 20);
  ctx.fillRect(240, 280, 8, 20);

  // Chameleon tail
  ctx.fillStyle = '#32CD32';
  ctx.beginPath();
  ctx.arc(160, 270, 10, 0, Math.PI * 2);
  ctx.fill();

  // Chameleon spots
  ctx.fillStyle = '#228B22';
  ctx.fillRect(180, 255, 8, 8);
  ctx.fillRect(200, 260, 8, 8);
  ctx.fillRect(220, 250, 8, 8);
  ctx.fillRect(245, 265, 8, 8);
};

