// Draw a kaleidoscope pattern with 6-fold symmetry
ctx.fillStyle = '#000';
ctx.fillRect(0, 0, W, H);

const centerX = W / 2;
const centerY = H / 2;
const radius = Math.min(W, H) / 2 - 10;

// Draw 6 segments
for (let i = 0; i < 6; i++) {
  const angle1 = (i * Math.PI) / 3;
  const angle2 = ((i + 1) * Math.PI) / 3;

  // Create a gradient for each segment
  const gradient = ctx.createLinearGradient(
    centerX + Math.cos(angle1) * radius,
    centerY + Math.sin(angle1) * radius,
    centerX + Math.cos(angle2) * radius,
    centerY + Math.sin(angle2) * radius
  );

  const hue = (i * 60) % 360;
  gradient.addColorStop(0, `hsl(${hue}, 100%, 50%)`);
  gradient.addColorStop(1, `hsl(${(hue + 60) % 360}, 100%, 30%)`);

  ctx.beginPath();
  ctx.moveTo(centerX, centerY);
  ctx.arc(centerX, centerY, radius, angle1, angle2);
  ctx.closePath();
  ctx.fillStyle = gradient;
  ctx.fill();

  // Add some pattern elements
  ctx.strokeStyle = `hsla(${(hue + 180) % 360}, 100%, 80%, 0.7)`;
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.arc(centerX, centerY, radius * 0.7, angle1, angle2);
  ctx.stroke();

  // Add small circles at the edge
  for (let j = 0; j < 5; j++) {
    const dist = radius * (0.2 + j * 0.15);
    const angle = angle1 + (angle2 - angle1) * (j / 5);
    ctx.beginPath();
    ctx.arc(
      centerX + Math.cos(angle) * dist,
      centerY + Math.sin(angle) * dist,
      3 + j,
      0,
      Math.PI * 2
    );
    ctx.fillStyle = `hsl(${(hue + 90 + j * 30) % 360}, 100%, 70%)`;
    ctx.fill();
  }
}

// Add a central pattern
for (let i = 0; i < 12; i++) {
  const angle = (i * Math.PI) / 6;
  const x = centerX + Math.cos(angle) * (radius * 0.3);
  const y = centerY + Math.sin(angle) * (radius * 0.3);
  ctx.fillStyle = `hsla(${(i * 30) % 360}, 100%, 60%, 0.8)`;
  ctx.beginPath();
  ctx.arc(x, y, 8, 0, Math.PI * 2);
  ctx.fill();
}

