      ctx.closePath();
      ctx.fill();
    } else {
      // Downward triangle
      ctx.beginPath();
      ctx.moveTo(x, y);
      ctx.lineTo(x + triangleSize, y);
      ctx.lineTo(x + triangleSize/2, y + triangleSize);
      ctx.closePath();
      ctx.fill();
    }
  }
}

