const drawCentaur = () => {
  // Clear canvas
  ctx.fillStyle = '#87CEEB';
  ctx.fillRect(0, 0, W, H);

  // Draw grass
  ctx.fillStyle = '#228B22';
  ctx.fillRect(0, 300, W, 100);

  // Draw horse body
  ctx.fillStyle = '#8B4513';
  ctx.fillRect(100, 200, 200, 100);

  // Draw horse legs
  ctx.fillRect(120, 280, 15, 60);
  ctx.fillRect(170, 280, 15, 60);
  ctx.fillRect(220, 280, 15, 60);
  ctx.fillRect(270, 280, 15, 60);

  // Draw horse head
  ctx.fillRect(300, 180, 60, 50);

  // Draw horse eye
  ctx.fillStyle = '#000';
  ctx.fillRect(345, 190, 5, 5);

  // Draw human torso
  ctx.fillStyle = '#FFD700';
  ctx.fillRect(150, 120, 100, 80);

  // Draw human head
  ctx.fillStyle = '#FFD700';
  ctx.fillRect(180, 80, 40, 40);

  // Draw human eye
  ctx.fillStyle = '#000';
  ctx.fillRect(195, 90, 5, 5);
  ctx.fillRect(215, 90, 5, 5);

  // Draw human hair
  ctx.fillStyle = '#8B4513';
  ctx.fillRect(180, 70, 40, 10);

  // Draw bow
  ctx.strokeStyle = '#8B4513';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(220, 120);
  ctx.lineTo(280, 100);
  ctx.stroke();

  // Draw bow string
  ctx.strokeStyle = '#FFFFFF';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(220, 120);
  ctx.lineTo(280, 100);
  ctx.stroke();

  // Draw arrow
  ctx.fillStyle = '#808080';
  ctx.fillRect(280, 100, 40, 3);
  ctx.fillStyle = '#8B4513';
  ctx.fillRect(315, 95, 10, 10);

  // Draw human arms
  ctx.fillStyle = '#FFD700';
  ctx.fillRect(130, 140, 20, 40);
  ctx.fillRect(250, 140, 20, 40);

  // Draw human hands
  ctx.fillStyle = '#FFD700';
  ctx.fillRect(120, 170, 10, 10);
  ctx.fillRect(280, 170, 10, 10);
};

drawCentaur();

