// Falling leaves
function drawLeaf(x, y, size, color) {
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.ellipse(x, y, size, size/2, 0, 0, Math.PI * 2);
    ctx.fill();

    // Leaf stem
    ctx.strokeStyle = '#8B4513';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(x, y + size/2);
    ctx.lineTo(x, y + size);
    ctx.stroke();
}

// Draw leaves with varying positions and colors
const leaves = [];
for (let i = 0; i < 50; i++) {
    leaves.push({
        x: Math.random() * W,
        y: Math.random() * H,
        size: Math.random() * 8 + 4,
        color: ['#FF4500', '#FF6347', '#FF8C00', '#FFA500'][Math.floor(Math.random() * 4)],
        speed: Math.random() * 2 + 1,
        sway: Math.random() * 2 - 1
    });
}

// Animation loop
function animate() {
    // Clear canvas with sky color
    ctx.fillStyle = '#87CEEB';
    ctx.fillRect(0, 0, W, H);

    // Draw ground and grass
    ctx.fillStyle = '#8B4513';
    ctx.fillRect(0, 300, W, 100);
    ctx.fillStyle = '#228B22';
    ctx.fillRect(0, 300, W, 20);

    // Draw wind effect
    ctx.strokeStyle = '#FFFFFF';
    ctx.lineWidth = 1;
    for (let y = 50; y < 300; y += 30) {
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(W, y);
        ctx.stroke();
    }

    // Update and draw leaves
    leaves.forEach(leaf => {
        leaf.y += leaf.speed;
        leaf.x += leaf.sway;

        // Reset leaf when it goes off screen
        if (leaf.y > H) {
            leaf.y = -10;
            leaf.x = Math.random() * W;
        }

        drawLeaf(leaf.x, leaf.y, leaf.size, leaf.color);
    });

    requestAnimationFrame(animate);
}

