    const angle = (i / 12) * Math.PI * 2;
    const x1 = 350 + Math.cos(angle) * 40;
    const y1 = 50 + Math.sin(angle) * 40;
    const x2 = 350 + Math.cos(angle) * 60;
    const y2 = 50 + Math.sin(angle) * 60;
    ctx.beginPath();
    ctx.moveTo(x1, y1);
    ctx.lineTo(x2, y2);
    ctx.stroke();
