// Background ground
ctx.fillStyle = '#3a3a5e';
ctx.fillRect(0, 300, W, 100);

// Stack of vinyl records
const recordColors = ['#e63946', '#457b9d', '#f4a261', '#2a9d8f', '#264653'];
const centerX = W/2;
const baseY = 280;

for (let i = 0; i < 5; i++) {
    const y = baseY - i * 15;
    const radius = 100 - i * 10;
    const innerRadius = radius * 0.2;

    // Outer ring
    ctx.fillStyle = recordColors[i];
    ctx.beginPath();
    ctx.arc(centerX, y, radius, 0, Math.PI * 2);
    ctx.fill();

    // Inner ring
    ctx.fillStyle = '#1a1a2e';
    ctx.beginPath();
    ctx.arc(centerX, y, innerRadius, 0, Math.PI * 2);
    ctx.fill();

    // Center label
    ctx.fillStyle = '#f8f9fa';
    ctx.beginPath();
    ctx.arc(centerX, y, innerRadius * 0.7, 0, Math.PI * 2);
    ctx.fill();

    // Groove lines
    ctx.strokeStyle = '#1a1a2e';
    ctx.lineWidth = 1;
    for (let j = 0; j < 12; j++) {
        const angle = (j / 12) * Math.PI * 2;
        const startRadius = radius * 0.3;
        const endRadius = radius * 0.95;
        const startX = centerX + Math.cos(angle) * startRadius;
        const startY = y + Math.sin(angle) * startRadius;
        const endX = centerX + Math.cos(angle) * endRadius;
        const endY = y + Math.sin(angle) * endRadius;

        ctx.beginPath();
        ctx.moveTo(startX, startY);
        ctx.lineTo(endX, endY);
        ctx.stroke();
    }
}

// Shadow under the stack
ctx.fillStyle = 'rgba(0, 0, 0, 0.2)';
ctx.beginPath();
ctx.ellipse(centerX, baseY + 5, 110, 10, 0, 0, Math.PI * 2);
ctx.fill();

