const triangleSize = 40;
const rows = Math.ceil(H / triangleSize);
const cols = Math.ceil(W / triangleSize);

// Define a limited palette
const colors = [
  '#FF6B6B', '#4ECDC4', '#45B7D1', '#96CEB4', 
  '#FFEAA7', '#DDA0DD', '#98D8C8', '#F7DC6F'
];

// Draw triangles in a grid pattern
for (let row = 0; row < rows; row++) {
  for (let col = 0; col < cols; col++) {
    const x = col * triangleSize;
    const y = row * triangleSize;

    // Randomly choose a color
    const color = colors[Math.floor(Math.random() * colors.length)];

    // Alternate triangle orientation for visual interest
    if ((row + col) % 2 === 0) {
      // Upward pointing triangle
      ctx.fillStyle = color;
      ctx.beginPath();
      ctx.moveTo(x, y + triangleSize);
      ctx.lineTo(x + triangleSize, y + triangleSize);
      ctx.lineTo(x + triangleSize/2, y);
      ctx.closePath();
      ctx.fill();
    } else {
      // Downward pointing triangle
      ctx.fillStyle = color;
      ctx.beginPath();
      ctx.moveTo(x, y);
      ctx.lineTo(x + triangleSize, y);
      ctx.lineTo(x + triangleSize/2, y + triangleSize);
      ctx.closePath();
      ctx.fill();
    }
  }
}

