function drawKaleidoscope() {
    // Clear canvas with dark background
    ctx.fillStyle = '#0a0a2a';
    ctx.fillRect(0, 0, W, H);

    // Center point
    const centerX = W / 2;
    const centerY = H / 2;

    // Draw radial patterns
    const numSectors = 12;
    const maxRadius = Math.min(W, H) * 0.4;

    // Create gradient for background
    const bgGradient = ctx.createRadialGradient(centerX, centerY, 0, centerX, centerY, maxRadius);
    bgGradient.addColorStop(0, '#1a1a4a');
    bgGradient.addColorStop(1, '#0a0a2a');

    ctx.fillStyle = bgGradient;
    ctx.beginPath();
    ctx.arc(centerX, centerY, maxRadius, 0, Math.PI * 2);
    ctx.fill();

    // Draw kaleidoscope triangles
    const colors = ['#ff3366', '#33ccff', '#33ff99', '#ffcc33', '#cc33ff', '#ff6633'];

    for (let i = 0; i < numSectors; i++) {
        const angle = (i * Math.PI * 2) / numSectors;
        const nextAngle = ((i + 1) * Math.PI * 2) / numSectors;

        // Draw triangle segments
        const segmentRadius = maxRadius * 0.8;
        const x1 = centerX + Math.cos(angle) * segmentRadius;
        const y1 = centerY + Math.sin(angle) * segmentRadius;
        const x2 = centerX + Math.cos(nextAngle) * segmentRadius;
        const y2 = centerY + Math.sin(nextAngle) * segmentRadius;

        ctx.beginPath();
        ctx.moveTo(centerX, centerY);
        ctx.lineTo(x1, y1);
        ctx.lineTo(x2, y2);
        ctx.closePath();

        // Use different colors for each segment
        ctx.fillStyle = colors[i % colors.length];
        ctx.globalAlpha = 0.7;
        ctx.fill();

        // Add highlight
        ctx.globalAlpha = 0.3;
        ctx.fillStyle = '#ffffff';
        ctx.beginPath();
        ctx.moveTo(centerX, centerY);
        ctx.lineTo(x1, y1);
        ctx.lineTo(x2, y2);
        ctx.closePath();
        ctx.fill();
    }

    // Draw central pattern
    ctx.globalAlpha = 1;
    const centerRadius = maxRadius * 0.2;
    const centerGradient = ctx.createRadialGradient(centerX, centerY, 0, centerX, centerY, centerRadius);
    centerGradient.addColorStop(0, '#ffffff');
    centerGradient.addColorStop(1, '#ff6633');

    ctx.fillStyle = centerGradient;
    ctx.beginPath();
    ctx.arc(centerX, centerY, centerRadius, 0, Math.PI * 2);
    ctx.fill();

    // Add some sparkle
    ctx.fillStyle = '#ffffff';
    for (let i = 0; i < 50; i++) {
        const angle = Math.random() * Math.PI * 2;
