    centerX, centerY, 0,
    centerX, centerY, bodyRadius
);
gradient.addColorStop(0, '#ff6bff');
gradient.addColorStop(1, '#c700ff');

ctx.fillStyle = gradient;
ctx.beginPath();
ctx.arc(centerX, centerY, bodyRadius, 0, Math.PI * 2);
ctx.fill();

// Jellyfish tentacles
const tentacleCount = 8;
const tentacleLength = 80;
const tentacleWidth = 8;

for (let i = 0; i < tentacleCount; i++) {
    const angle = (i / tentacleCount) * Math.PI * 2;
    const startX = centerX + Math.cos(angle) * bodyRadius;
    const startY = centerY + Math.sin(angle) * bodyRadius;

    // Tentacle gradient
    const tentacleGradient = ctx.createLinearGradient(
        startX, startY,
        startX, startY + tentacleLength
    );
    tentacleGradient.addColorStop(0, '#ff6bff');
    tentacleGradient.addColorStop(1, '#9d00ff');

    ctx.strokeStyle = tentacleGradient;
    ctx.lineWidth = tentacleWidth;
    ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.moveTo(startX, startY);
    ctx.lineTo(
        startX + Math.cos(angle) * tentacleLength * 0.8,
