    // Trunk
    ctx.fillStyle = '#5d4037';
    ctx.fillRect(x - size/6, y, size/3, size/2);

    // Tree
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.moveTo(x - size/2, y);
    ctx.lineTo(x, y - size);
